INSERT INTO running_shoes ("brand","model","slug","series_name","version_number","category","weight","availability","available_from","heel_stack_height","forefoot_stack_height","heel_to_toe_drop","cushioning_level","stability","has_carbon_plate","has_super_foam","price","best_for","release_year","description","source_url","data_source","last_verified","durability_rating","responsiveness_rating","comfort_rating") VALUES ('Nnormal','Cadí GTX','nnormal-cadi-gtx','Cadí GTX',NULL,'trail',NULL,'available',NULL,35,29,6,'soft','neutral',NULL,NULL,195,'["trails","long_runs"]',2026,'The waterproof Cadí road-to-trail model, distinct from the standard Cadí. NNormal lists a GORE-TEX Invisible Fit ePE membrane, Vibram Megagrip outsole with 4 mm lugs and a nominal 35/29 mm stack. The listing does not publish a comparable size-specific weight. Consider this for easy trails in wet weather; try the exact upper before buying.','https://www.nnormal.com/en_US/men/shoes/cadi/nnormal-cadi_gtx_men_blue_black-NX4CD1M-001','manufacturer','2026-11-14T00:00:00.000Z',NULL,NULL,NULL) ON CONFLICT(slug) DO NOTHING;
