INSERT INTO "_shoe_catalog_import_guard" SELECT CASE WHEN EXISTS(SELECT 1 FROM running_shoes WHERE id=792 AND slug='nike-alphafly-4' AND (("availability" IS 'upcoming' AND "available_from" IS '2026-10-29' AND "weight" IS NULL AND "heel_stack_height" IS NULL AND "forefoot_stack_height" IS NULL AND "last_verified" IS '2026-09-26T00:00:00.000Z') OR ("brand" IS 'Nike' AND "model" IS 'Alphafly 4' AND "slug" IS 'nike-alphafly-4' AND "series_name" IS 'Alphafly' AND "version_number" IS 4 AND "category" IS 'racing' AND "weight" IS 6.7 AND "availability" IS 'available' AND "available_from" IS '2026-10-29' AND "heel_stack_height" IS 42 AND "forefoot_stack_height" IS 34 AND "heel_to_toe_drop" IS 8 AND "cushioning_level" IS 'soft' AND "stability" IS 'neutral' AND "has_carbon_plate" IS 1 AND "has_super_foam" IS 1 AND "price" IS 279.95 AND "best_for" IS '["racing","long_runs"]' AND "release_year" IS 2026 AND "description" IS 'Nike''s marathon racer combines ZoomX LT above a wider carbon Flyplate, ZoomX below it and dual forefoot Air Zoom units. Running Warehouse lists the men''s Proto in stock and measures 6.7 oz and 42/34 mm. These are retailer measurements, not competition certification; runners entering regulated events should check the exact approved model and applicable rules.' AND "source_url" IS 'https://www.runningwarehouse.com/Nike_Alphafly_4/descpage-NAFL4M1.html' AND "data_source" IS 'running_warehouse' AND "last_verified" IS '2026-11-14T00:00:00.000Z' AND "durability_rating" IS NULL AND "responsiveness_rating" IS NULL AND "comfort_rating" IS NULL))) THEN 1 ELSE 0 END;
